    Ciphertext r3 = a + e2;
    Ciphertext r4 = a - e2;
    Ciphertext r5 = (d[5] - d[3]) - (e2 + e2);
    return {r0, r1, r2, r3, r4, r5};
  }
  return {d[1], d[0] - d[1], d[2] - d[1], d[2], d[3]};
}

vector<Ciphertext> kerT(const vector<Ciphertext> &g, int n, bool needT5 = true)
{
