    Ciphertext s2 = s34 + s34;
    Ciphertext y2 = (s2 + s2) - sm;
    Ciphertext d4 = d2 + d2;
    Ciphertext y3 = (dm + (d4 + d4)) + m[5];
    return {y0, y1, y2, y3};
  }
  return {m[0] + m[1] + m[3], m[0] + m[2] + m[4]};
}

